475	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
476	    debug!(
477	        "complete_subcommand: cmd={:?}, value={:?}",
478	        cmd.get_name(),
479	        value
480	    );
481	
482	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
483	        .into_iter()
484	        .filter(|x| x.get_value().starts_with(value))
485	        .collect();
486	    if cmd.is_allow_external_subcommands_set() {
487	        let external_completer = cmd.get::<SubcommandCandidates>();
488	        if let Some(completer) = external_completer {
489	            scs.extend(complete_value_candidates_str(
490	                value,
491	                completer.value_candidates(),
492	            ));
493	        }
494	    }
495	
496	    scs.sort();
497	    scs.dedup();
498	    scs
499	}
